var ids=['signin','new-conversation','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work','conversation--rail','activity--work--rail'];
function visit(l,f){f(l);(l.layers||[]).forEach(function(c){visit(c,f);});}
['Light/Clean','Dark/Clean'].forEach(function(app){var p=H.page('Proto macOS '+app.split('/')[0]);ids.forEach(function(id){var matches=p.layers.filter(function(l){return l.name==='Screen/macos/'+app+'/'+id;});if(matches.length!==1)throw Error(id+' count '+matches.length);var s=matches[0],borders=[],links=[],regions={};visit(s,function(l){if(l.style&&(l.style.borders||[]).some(function(b){return b.enabled;})&&l.name.indexOf('traffic-')!==0&&['track','arc'].indexOf(l.name)<0)borders.push(l.name);if(l.name.indexOf('link:')===0)links.push(l.name);if(['sidebar','content-col','inspector','search-field','conversation-menu','alert','session','inspector-body'].indexOf(l.name)>=0)regions[l.name]={x:l.frame.x,y:l.frame.y,w:l.frame.width,h:l.frame.height};});console.log(JSON.stringify({id:id,app:app,frame:String(s.id),w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,parent:p.name,borders:borders,regions:regions,links:links}));});});
